2	/**
3	 * Sklad. Data jsou v stock_items (spravuje novy e-shop), rezervace v JSONu.
4	 */
5	
6	namespace App\Legacy\Admin;
7	
8	use App\Legacy\lib\StockReport;
9	
10	class StockController extends BaseController
11	{
12	    protected $title = 'Sklad';
13	
14	    public function listAction()
15	    {
16	        global $db;
17	        legacy_db();
18	
19	        $onlyLow = get_param('low') == '1';
20	        $rows = $onlyLow ? StockReport::lowStock() : StockReport::all();
21	
22	        // produkty bez zaznamu ve skladu
23	        $missing = $db->query("SELECT p.id, p.name, p.sku FROM products p LEFT JOIN stock_items s ON s.product_id = p.id WHERE s.product_id IS NULL AND p.active = 1");
24	
25	        $totalOnHand = 0;
26	        $totalReserved = 0;
27	        foreach ($rows as $r) {
28	            $totalOnHand += (int) $r['on_hand'];
29	            $totalReserved += (int) $r['reserved'];
30	        }
31	
32	        return $this->renderLayout('stock/list', array(
33	            'rows'          => $rows,
34	            'missing'       => $missing,
35	            'onlyLow'       => $onlyLow,
36	            'totalOnHand'   => $totalOnHand,
37	            'totalReserved' => $totalReserved,
38	            'orphans'       => StockReport::orphanReservations(),
39	        ));
40	    }
41	
42	    /**
43	     * Detail rezervaci produktu.
44	     */
45	    public function reservationsAction()
46	    {
47	        global $db;
48	        legacy_db();
49	        $pid = get_param('product');
50	        $res = StockReport::reservations($pid);
51	        $rows = array();
52	        foreach ($res as $orderId => $qty) {
53	            $o = $db->one("SELECT status, placed_at FROM orders WHERE id = '" . $orderId . "'");
54	            $rows[] = array(
55	                'Objednávka' => $orderId,
56	                'Kusů'       => (int) $qty,
57	                'Stav'       => $o ? order_state_label($o['status']) : '(neexistuje)',
58	                'Datum'      => $o ? format_date($o['placed_at']) : '',
59	            );
60	        }
61	
62	        return $this->renderLayout('partials/table', array(
63	            'heading' => 'Rezervace produktu ' . product_name($pid),
64	            'columns' => array('Objednávka', 'Kusů', 'Stav', 'Datum'),
65	            'rows'    => $rows,
66	        ), 'Rezervace');
67	    }
68	
69	    /**
70	     * Inventura – rucni prepis stavu.
71	     */
72	    public function inventoryAction()
73	    {
74	        auth_require('sklad');
75	        if (is_post()) {
76	            csrf_check();
77	            $qty = post_param('qty', array());
78	            if (is_array($qty)) {
79	                foreach ($qty as $pid => $q) {
80	                    if ($q === '') {
81	                        continue;
82	                    }
83	                    StockReport::setOnHand($pid, (int) $q);
84	                }
85	            }
86	            flash('Inventura uložena');
87	
88	            return $this->redirect(admin_url('stock'));
89	        }
90	
91	        return $this->renderLayout('stock/list', array(
92	            'rows'          => StockReport::all(),
93	            'missing'       => array(),
94	            'onlyLow'       => false,
95	            'totalOnHand'   => 0,
96	            'totalReserved' => 0,
97	            'orphans'       => array(),
98	            'inventory'     => true,
99	        ), 'Inventura');
100	    }
101	}
